  Hypothesis Hz_bl0 : bc <> 0 -> gz M0 bl (8 * bc).
  Hypothesis Hz_nd0 : forall p k v, In (p, (k, v)) ents -> gz M0 p NS.
  Hypothesis Hk0 : shk M0 keyp k0.
  Hypothesis Hk0c : k0 = 0 \/ (0 < k0 < 8 /\ keyp mod 8 + 3 < k0).
  Hypothesis Hsp16 : sp0 mod 16 = 0.
  Hypothesis Hsplo : 2 ^ 45 <= sp0 - 16.
  Hypothesis Hsphi : sp0 <= 2 ^ 47.
  Hypothesis Hroom : stack_room ASEGS M0 sp0 16.
