  Ltac runL R vals scr pc :=
    let E := fresh "E" in let HR := fresh "HR" in let HK := fresh "HK" in
    pose (E := Eseed R vals);
    assert (HR : regs_ok E srL R) by
      (apply regs_ok_srs; [apply regs_ok_seed|];
       repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | evs; first [assumption | match goal with H : getr R 13%bv = _ |- _ => rewrite H; reflexivity end]] |]); apply Forall_nil);
    assert (HK : know_ok ASEGS E M1 (KNBx pc srL scr)) by (kn_eval; knowB_tac);
    xrun HR HK 100%nat STOPS scr 50%N;
    [ split_scs; try sc_auto1; try sc_shdj;
      try (match goal with Hk : cell4 _ _ _ _ |- _ => unfold cell4 in Hk; sc_rd_sx Hk end);
      try (cbn [sc_denot]; evs; rewrite ?w_remu by lia; rewrite ?br_ne, ?br_eq, ?br_ltu, ?br_geu, ?br_ne_sxw by lia; bool_lia)
    | ].

  Ltac finL_ret r :=
    match goal with HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
    let AO := fresh "AO" in
    assert (AO : aonlyTS _ R') by (eapply aonlyTS_of_syms; [exact HR'| vm_cast_no_check (@eq_refl bool true)]);
    let G10 := fresh "G" in rreg HR' 10%bv G10; let G2 := fresh "G" in rreg HR' 2%bv G2;
    let G1 := fresh "G" in rreg HR' 1%bv G1;
    let G2' := fresh "G" in assert (G2' : getr R' 2%bv = Z_to_bv 64 sp0) by (rewrite G2; rewrite ?w_addm, ?w_add by lia; f_equal; lia);
    let G10' := fresh "G" in assert (G10' : getr R' 10%bv = Z_to_bv 64 r) by (rewrite G10; reflexivity);
    exact (conj Hms (conj AO (conj G10' (conj G2' G1))))
    end.

  Lemma loopM : forall l2 l1 p k v R,
    ents = l1 ++ (p, (k, v)) :: l2 -> bc <> 0 ->
    getr R 10%bv = Z_to_bv 64 p -> getr R 12%bv = Z_to_bv 64 bc -> getr R 13%bv = Z_to_bv 64 SHBASE ->
    getr R 14%bv = Z_to_bv 64 key -> getr R 15%bv = Z_to_bv 64 (hmod key bc) -> getr R 16%bv = sxw key ->
    getr R 2%bv = Z_to_bv 64 (sp0 - 16) -> getr R 1%bv = ret ->
    exists R' r, found r /\
      ((msteps ASEGS (st R LM_PC M1) (st R' RET1 M1) /\ atRet R R' r) \/ (msteps ASEGS (st R LM_PC M1) (st R' RET2 M1) /\ atRet R R' r)).
Proof.
